window.__PACK__=window.__PACK__||{};window.__PACK__["b_1792499587012"]={"rev":"ak9lss","lessons":[{"id":"l_1792499816788","title":"1","fullHtml":"<!-- TAB: محتوا -->\n<h2 style=\"color:#34d399; margin-bottom:15px;\">🔬 درس اول: زنگ علوم</h2>\n<p style=\"color:#cbd5e1; line-height:1.9;\">دانشمندان برای کشف پدیده‌های اطراف خود، ابتدا مشاهده می‌کنند، سپس پرسش‌هایی در ذهنشان ایجاد می‌شود. آنها برای یافتن پاسخ، پیش‌بینی (فرضیه) می‌کنند و با انجام آزمایش (کاوشگری) به نتیجه می‌رسند.</p>\n\n<h3 style=\"color:#6ee7b7; margin-top:20px;\">مراحل کاوشگری</h3>\n<div style=\"background:rgba(16,185,129,0.1); border-right:4px solid #10b981; padding:15px; border-radius:10px; margin:15px 0; line-height:2;\">\n    <strong>۱. مشاهده:</strong> توجه به پدیده‌ها (مثل دیرتر رسیدن بعضی فرفره‌ها به زمین).<br>\n    <strong>۲. پرسش:</strong> چرا این اتفاق می‌افتد؟<br>\n    <strong>۳. پیش‌بینی (فرضیه):</strong> پاسخ حدسی و scientific به پرسش.<br>\n    <strong>۴. آزمایش:</strong> بررسی درستی پیش‌بینی با تغییر دادن یک چیز و اندازه‌گیری چیز دیگر.<br>\n    <strong>۵. نتیجه‌گیری:</strong> ثبت مشاهدات و رسیدن به جواب.\n</div>\n\n<h3 style=\"color:#6ee7b7; margin-top:20px;\">متغیرها در آزمایش</h3>\n<ul style=\"color:#cbd5e1; line-height:2; padding-right:20px;\">\n    <li><strong>چه چیزی را تغییر دادیم؟</strong> (متغیر مستقل) مثلاً پهنای بال فرفره.</li>\n    <li><strong>چه چیزی را اندازه گرفتیم؟</strong> (متغیر وابسته) مثلاً زمان رسیدن فرفره به زمین.</li>\n    <li><strong>چه چیزهایی را تغییر ندادیم؟</strong> (متغیرهای کنترل شده) مثلاً طول بال، جرم، ارتفاع رها کردن.</li>\n</ul>\n\n<!-- TAB: نمودار درختی -->\n<h2 style=\"color:#34d399; margin-bottom:15px;\">🌳 نمودار درختی زنگ علوم</h2>\n<div class=\"xmind-container\">\n    <div class=\"xmind-root\">روش علمی</div>\n    <div class=\"xmind-branches\">\n        <div class=\"xmind-branch\"><div class=\"xmind-node\"><strong>مشاهده</strong>دیدن پدیده‌ها</div></div>\n        <div class=\"xmind-branch\"><div class=\"xmind-node\"><strong>پرسش</strong>ایجاد سوال</div></div>\n        <div class=\"xmind-branch\"><div class=\"xmind-node\"><strong>فرضیه</strong>پیش‌بینی پاسخ</div></div>\n        <div class=\"xmind-branch\"><div class=\"xmind-node\"><strong>آزمایش</strong>تغییر یک عامل</div></div>\n        <div class=\"xmind-branch\"><div class=\"xmind-node\"><strong>نتیجه‌گیری</strong>ثبت مشاهدات</div></div>\n    </div>\n</div>\n\n<!-- TAB: نکات امتحانی -->\n<h2 style=\"color:#34d399; margin-bottom:15px;\">📝 نکات امتحانی درس اول</h2>\n<div style=\"background:rgba(255,255,255,0.04); border:1px solid rgba(255,255,255,0.08); border-radius:14px; padding:16px 20px; margin-bottom:14px;\">\n    <h4 style=\"color:#fbbf24; margin-bottom:8px; font-size:1rem;\">⚠️ نکته ۱: شرایط آزمایش</h4>\n    <p style=\"font-size:0.9rem; color:#cbd5e1; line-height:1.8; margin:0;\">در هر آزمایش برای اینکه نتیجه دقیق باشد، فقط باید <strong>یک چیز</strong> را تغییر دهیم و بقیه شرایط را یکسان نگه داریم.</p>\n</div>\n<div style=\"background:rgba(255,255,255,0.04); border:1px solid rgba(255,255,255,0.08); border-radius:14px; padding:16px 20px; margin-bottom:14px;\">\n    <h4 style=\"color:#fbbf24; margin-bottom:8px; font-size:1rem;\">⚠️ نکته ۲: تکرار آزمایش</h4>\n    <p style=\"font-size:0.9rem; color:#cbd5e1; line-height:1.8; margin:0;\">دانشمندان برای اطمینان از درستی نتایج، آزمایش را چندین بار تکرار می‌کنند.</p>\n</div>\n\n<!-- TAB: آزمون -->\n<h2 style=\"color:#34d399; margin-bottom:15px;\">🧪 آزمون درس اول</h2>\n<div style=\"background:rgba(255,255,255,0.04); border:1px solid rgba(255,255,255,0.08); border-radius:14px; padding:20px; margin-bottom:18px;\">\n    <h4 style=\"color:#e2e8f0; margin-bottom:14px;\">۱. کدام‌یک از مراحل زیر در روش علمی، قبل از «آزمایش» قرار می‌گیرد؟</h4>\n    <div style=\"color:#cbd5e1; line-height:2;\">الف) نتیجه‌گیری &nbsp;&nbsp; <strong>ب) پیش‌بینی (فرضیه)</strong> &nbsp;&nbsp; ج) ثبت مشاهدات</div>\n</div>\n<div style=\"background:rgba(255,255,255,0.04); border:1px solid rgba(255,255,255,0.08); border-radius:14px; padding:20px; margin-bottom:18px;\">\n    <h4 style=\"color:#e2e8f0; margin-bottom:14px;\">۲. در آزمایش «فرفره چرخان»، اگر پهنای بال را تغییر دهیم، چه چیزی را باید اندازه بگیریم؟</h4>\n    <div style=\"color:#cbd5e1; line-height:2;\">الف) طول بال &nbsp;&nbsp; <strong>ب) زمان رسیدن به زمین</strong> &nbsp;&nbsp; ج) جنس کاغذ</div>\n</div>\n<div style=\"background:rgba(251,191,36,0.15); border-right:4px solid #fbbf24; padding:15px; border-radius:10px; color:#fde68a;\">\n    💡 <strong>پاسخ‌نامه:</strong> ۱ (ب)، ۲ (ب)\n</div>\n\n<!-- TAB: گام به گام -->\n<h2 style=\"color:#34d399; margin-bottom:15px;\">✍️ گام به گام درس اول</h2>\n<h3 style=\"color:#6ee7b7; margin-top:20px;\">پاسخ جدول صفحه ۱۲ (نتیجه کاوش فرفره)</h3>\n<p style=\"color:#cbd5e1;\">فرفره‌ای که بال پهن‌تری دارد، <strong>دیرتر</strong> به سطح زمین می‌رسد؛ بنابراین، هر چه <strong>پهنای</strong> بال فرفره <strong>بیشتر</strong> باشد، زمان رسیدن آن به سطح زمین <strong>بیشتر</strong> می‌شود.</p>\n\n<h3 style=\"color:#6ee7b7; margin-top:20px;\">پاسخ جدول صفحه ۱۳ (عوامل موثر بر زمان فرود)</h3>\n<ul style=\"color:#cbd5e1; line-height:2;\">\n    <li><strong>چه چیزی را باید تغییر داد؟</strong> طول بال فرفره</li>\n    <li><strong>چه چیزی را باید اندازه گرفت؟</strong> زمان رسیدن فرفره به زمین</li>\n    <li><strong>چه چیزهایی را نباید تغییر داد؟</strong> پهنای بال، جرم و جنس کاغذ، ارتفاع رها کردن</li>\n</ul>","r":"1lljkvx"},{"id":"l_1792499818925","title":"2","fullHtml":"<!-- TAB: محتوا -->\n<h2 style=\"color:#34d399; margin-bottom:15px;\">🧪 درس دوم: ماده تغییر می‌کند</h2>\n<p style=\"color:#cbd5e1; line-height:1.9;\">ما در زندگی روزانه برای برطرف کردن نیازهایمان، مواد اطراف خود را تغییر می‌دهیم. این تغییرها به دو دسته کلی تقسیم می‌شوند: تغییرات فیزیکی و تغییرات شیمیایی.</p>\n\n<h3 style=\"color:#6ee7b7; margin-top:20px;\">تغییرات فیزیکی</h3>\n<p style=\"color:#cbd5e1; line-height:1.9;\">در این تغییرها، شکل و اندازه‌ی ماده تغییر می‌کند؛ ولی <strong>جنس ماده تغییری نمی‌کند</strong> و ماده جدیدی به وجود نمی‌آید. مانند: تا کردن لباس، تکه کردن نان، حل شدن شکر در چای، بریدن کاغذ.</p>\n\n<h3 style=\"color:#6ee7b7; margin-top:20px;\">تغییرات شیمیایی</h3>\n<p style=\"color:#cbd5e1; line-height:1.9;\">در این تغییرها، ماده اولیه به <strong>ماده جدیدی</strong> تبدیل می‌شود. در بیشتر این تغییرها رنگ، بو و مزه ماده تغییر می‌کند. مانند: سوختن قند، پختن نان، فاسد شدن میوه، ترش شدن شیر، زنگ زدن آهن.</p>\n\n<!-- TAB: نمودار درختی -->\n<h2 style=\"color:#34d399; margin-bottom:15px;\">🌳 نمودار درختی تغییرات ماده</h2>\n<div class=\"xmind-container\">\n    <div class=\"xmind-root\">تغییرات ماده</div>\n    <div class=\"xmind-branches\">\n        <div class=\"xmind-branch\"><div class=\"xmind-node\"><strong>فیزیکی</strong>تغییر شکل و اندازه (ماده جدید نمی‌شود)</div></div>\n        <div class=\"xmind-branch\"><div class=\"xmind-node\"><strong>شیمیایی</strong>تولید ماده جدید (تغییر رنگ، بو، مزه)</div></div>\n    </div>\n</div>\n\n<!-- TAB: نکات امتحانی -->\n<h2 style=\"color:#34d399; margin-bottom:15px;\">📝 نکات امتحانی درس دوم</h2>\n<div style=\"background:rgba(255,255,255,0.04); border:1px solid rgba(255,255,255,0.08); border-radius:14px; padding:16px 20px; margin-bottom:14px;\">\n    <h4 style=\"color:#fbbf24; margin-bottom:8px; font-size:1rem;\">⚠️ نکته ۱: تفاوت تغییر فیزیکی و شیمیایی</h4>\n    <p style=\"font-size:0.9rem; color:#cbd5e1; line-height:1.8; margin:0;\">اگر بعد از تغییر، ماده جدیدی تولید شود، تغییر شیمیایی است. اگر فقط ظاهر عوض شود، فیزیکی است.</p>\n</div>\n<div style=\"background:rgba(255,255,255,0.04); border:1px solid rgba(255,255,255,0.08); border-radius:14px; padding:16px 20px; margin-bottom:14px;\">\n    <h4 style=\"color:#fbbf24; margin-bottom:8px; font-size:1rem;\">⚠️ نکته ۲: سرعت تغییرات</h4>\n    <p style=\"font-size:0.9rem; color:#cbd5e1; line-height:1.8; margin:0;\">برخی تغییرات شیمیایی سریع (مثل سوختن کبریت) و برخی کند (مثل زنگ زدن آهن) هستند.</p>\n</div>\n\n<!-- TAB: آزمون -->\n<h2 style=\"color:#34d399; margin-bottom:15px;\">🧪 آزمون درس دوم</h2>\n<div style=\"background:rgba(255,255,255,0.04); border:1px solid rgba(255,255,255,0.08); border-radius:14px; padding:20px; margin-bottom:18px;\">\n    <h4 style=\"color:#e2e8f0; margin-bottom:14px;\">۱. کدام‌یک از موارد زیر یک تغییر شیمیایی است؟</h4>\n    <div style=\"color:#cbd5e1; line-height:2;\">الف) خرد کردن چوب &nbsp;&nbsp; ب) ذوب شدن یخ &nbsp;&nbsp; <strong>ج) پختن تخم‌مرغ</strong> &nbsp;&nbsp; د) بافتن شال گردن</div>\n</div>\n<div style=\"background:rgba(255,255,255,0.04); border:1px solid rgba(255,255,255,0.08); border-radius:14px; padding:20px; margin-bottom:18px;\">\n    <h4 style=\"color:#e2e8f0; margin-bottom:14px;\">۲. در کدام تغییر، ماده اولیه به ماده جدید تبدیل نمی‌شود؟</h4>\n    <div style=\"color:#cbd5e1; line-height:2;\">الف) فاسد شدن میوه &nbsp;&nbsp; <strong>ب) تکه کردن نان</strong> &nbsp;&nbsp; ج) سوختن کاغذ</div>\n</div>\n<div style=\"background:rgba(251,191,36,0.15); border-right:4px solid #fbbf24; padding:15px; border-radius:10px; color:#fde68a;\">\n    💡 <strong>پاسخ‌نامه:</strong> ۱ (ج)، ۲ (ب)\n</div>\n\n<!-- TAB: گام به گام -->\n<h2 style=\"color:#34d399; margin-bottom:15px;\">✍️ گام به گام درس دوم</h2>\n<h3 style=\"color:#6ee7b7; margin-top:20px;\">پاسخ جدول صفحه ۲۰ (تغییرهای محیط اطراف)</h3>\n<table style=\"width:100%; border-collapse:collapse; margin:15px 0; background:rgba(255,255,255,0.05); border-radius:10px; overflow:hidden; text-align:center;\">\n    <tr style=\"background:rgba(5,150,105,0.3); color:#fff;\">\n        <th style=\"padding:10px;\">نام ماده</th>\n        <th style=\"padding:10px;\">کاری که انجام شده است</th>\n        <th style=\"padding:10px;\">نوع تغییر</th>\n    </tr>\n    <tr style=\"border-bottom:1px solid rgba(255,255,255,0.1);\">\n        <td style=\"padding:10px; color:#cbd5e1;\">کاغذ</td>\n        <td style=\"padding:10px; color:#cbd5e1;\">بریدن</td>\n        <td style=\"padding:10px; color:#fde68a;\">فیزیکی</td>\n    </tr>\n    <tr style=\"border-bottom:1px solid rgba(255,255,255,0.1);\">\n        <td style=\"padding:10px; color:#cbd5e1;\">چوب و نُخ</td>\n        <td style=\"padding:10px; color:#cbd5e1;\">بریدن</td>\n        <td style=\"padding:10px; color:#fde68a;\">فیزیکی</td>\n    </tr>\n    <tr>\n        <td style=\"padding:10px; color:#cbd5e1;\">نخ</td>\n        <td style=\"padding:10px; color:#cbd5e1;\">بستن و گره زدن</td>\n        <td style=\"padding:10px; color:#fde68a;\">فیزیکی</td>\n    </tr>\n</table>","r":"4fgmmf"},{"id":"l_1792499821108","title":"3","fullHtml":"<!-- TAB: محتوا -->\n<h2 style=\"color:#34d399; margin-bottom:15px;\">🌈 درس سوم: رنگین کمان</h2>\n<p style=\"color:#cbd5e1; line-height:1.9;\">نور خورشید (نور سفید) در واقع مخلوطی از رنگ‌های گوناگون است. وقتی نور خورشید از میان قطرات آب باران عبور می‌کند، این قطرات مانند یک منشور عمل کرده و نور را به رنگ‌های مختلف تجزیه می‌کنند و رنگین کمان ایجاد می‌شود.</p>\n\n<h3 style=\"color:#6ee7b7; margin-top:20px;\">عدسی‌ها (ذره‌بین)</h3>\n<p style=\"color:#cbd5e1; line-height:1.9;\">ذره‌بین یا عدسی، وسیله‌ای است که از شیشه یا پلاستیک شفاف ساخته شده و نور را در یک نقطه جمع می‌کند. به این نقطه، <strong>کانون</strong> عدسی می‌گویند.</p>\n<ul style=\"color:#cbd5e1; line-height:2; padding-right:20px;\">\n    <li>ذره‌بین می‌تواند تصویر اجسام را بزرگ‌تر نشان دهد.</li>\n    <li>اگر نور خورشید را روی کاغذ جمع کنیم، کاغذ می‌سوزد.</li>\n    <li>از عدسی‌ها در ساخت عینک، دوربین عکاسی، تلسکوپ و میکروسکوپ استفاده می‌شود.</li>\n</ul>\n\n<!-- TAB: نمودار درختی -->\n<h2 style=\"color:#34d399; margin-bottom:15px;\">🌳 نمودار درختی رنگین کمان</h2>\n<div class=\"xmind-container\">\n    <div class=\"xmind-root\">نور و عدسی</div>\n    <div class=\"xmind-branches\">\n        <div class=\"xmind-branch\"><div class=\"xmind-node\"><strong>رنگین کمان</strong>تجزیه نور سفید توسط قطرات آب</div></div>\n        <div class=\"xmind-branch\"><div class=\"xmind-node\"><strong>ذره‌بین (عدسی)</strong>جمع کردن نور در کانون</div></div>\n        <div class=\"xmind-branch\"><div class=\"xmind-node\"><strong>کاربرد عدسی‌ها</strong>عینک، دوربین، تلسکوپ</div></div>\n    </div>\n</div>\n\n<!-- TAB: نکات امتحانی -->\n<h2 style=\"color:#34d399; margin-bottom:15px;\">📝 نکات امتحانی درس سوم</h2>\n<div style=\"background:rgba(255,255,255,0.04); border:1px solid rgba(255,255,255,0.08); border-radius:14px; padding:16px 20px; margin-bottom:14px;\">\n    <h4 style=\"color:#fbbf24; margin-bottom:8px; font-size:1rem;\">⚠️ نکته ۱: مسیر نور</h4>\n    <p style=\"font-size:0.9rem; color:#cbd5e1; line-height:1.8; margin:0;\">نور همیشه در خط راست حرکت می‌کند، اما وقتی وارد آب یا شیشه می‌شود، مسیرش می‌شکند (شکست نور).</p>\n</div>\n<div style=\"background:rgba(255,255,255,0.04); border:1px solid rgba(255,255,255,0.08); border-radius:14px; padding:16px 20px; margin-bottom:14px;\">\n    <h4 style=\"color:#fbbf24; margin-bottom:8px; font-size:1rem;\">⚠️ نکته ۲: ذره‌بین</h4>\n    <p style=\"font-size:0.9rem; color:#cbd5e1; line-height:1.8; margin:0;\">ذره‌بین نور را جمع می‌کند، بنابراین اگر برای مدت طولانی روی یک نقطه بماند، باعث ایجاد گرما و سوختن می‌شود.</p>\n</div>\n\n<!-- TAB: آزمون -->\n<h2 style=\"color:#34d399; margin-bottom:15px;\">🧪 آزمون درس سوم</h2>\n<div style=\"background:rgba(255,255,255,0.04); border:1px solid rgba(255,255,255,0.08); border-radius:14px; padding:20px; margin-bottom:18px;\">\n    <h4 style=\"color:#e2e8f0; margin-bottom:14px;\">۱. رنگین کمان چگونه تشکیل می‌شود؟</h4>\n    <div style=\"color:#cbd5e1; line-height:2;\">الف) انعکاس نور از خورشید &nbsp;&nbsp; <strong>ب) تجزیه نور خورشید توسط قطرات آب</strong> &nbsp;&nbsp; ج) جذب نور توسط زمین</div>\n</div>\n<div style=\"background:rgba(255,255,255,0.04); border:1px solid rgba(255,255,255,0.08); border-radius:14px; padding:20px; margin-bottom:18px;\">\n    <h4 style=\"color:#e2e8f0; margin-bottom:14px;\">۲. کانون عدسی کجاست؟</h4>\n    <div style=\"color:#cbd5e1; line-height:2;\">الف) مرکز عدسی &nbsp;&nbsp; <strong>ب) نقطه‌ای که نور در آن جمع می‌شود</strong> &nbsp;&nbsp; ج) لبه عدسی</div>\n</div>\n<div style=\"background:rgba(251,191,36,0.15); border-right:4px solid #fbbf24; padding:15px; border-radius:10px; color:#fde68a;\">\n    💡 <strong>پاسخ‌نامه:</strong> ۱ (ب)، ۲ (ب)\n</div>\n\n<!-- TAB: گام به گام -->\n<h2 style=\"color:#34d399; margin-bottom:15px;\">✍️ گام به گام درس سوم</h2>\n<p style=\"color:#cbd5e1; line-height:1.9;\"><strong>آزمایش صفحه ۲۹ (بررسی ذره‌بین):</strong> وقتی نور خورشید به ذره‌بین می‌تابد، ذره‌بین نور را در یک نقطه (کانون) جمع می‌کند. به همین دلیل در آن نقطه گرمای زیادی ایجاد می‌شود و کاغذ می‌سوزد.</p>\n<p style=\"color:#cbd5e1; line-height:1.9;\"><strong>آزمایش صفحه ۳۱ (تشکیل تصویر شمع):</strong> ذره‌بین تصویر شمع را به صورت وارونه روی کاغذ نشان می‌دهد. با جابه‌جا کردن ذره‌بین، اندازه تصویر تغییر می‌کند (کوچک‌تر یا بزرگ‌تر می‌شود).</p>","r":"9a9p5b"},{"id":"l_1792499823085","title":"4","fullHtml":"<!-- TAB: محتوا -->\n<h2 style=\"color:#34d399; margin-bottom:15px;\">🦕 درس چهارم: برگی از تاریخ زمین</h2>\n<p style=\"color:#cbd5e1; line-height:1.9;\">در گذشته‌های بسیار دور، جاندارانی روی زمین زندگی می‌کردند که اکنون از بین رفته‌اند. آثاری که از آنها باقی مانده است، به ما درباره گذشته زمین اطلاعات می‌دهد.</p>\n\n<h3 style=\"color:#6ee7b7; margin-top:20px;\">فسیل چیست؟</h3>\n<p style=\"color:#cbd5e1; line-height:1.9;\">به آثار و بقایای گیاهان و جانورانی که پس از سال‌ها در بین لایه‌های رسوبی زمین باقی مانده‌اند، <strong>فسیل</strong> می‌گویند. قسمت‌های سخت بدن (مانند استخوان، دندان و صدف) بیشتر به فسیل تبدیل می‌شوند.</p>\n\n<h3 style=\"color:#6ee7b7; margin-top:20px;\">لایه‌های رسوبی</h3>\n<p style=\"color:#cbd5e1; line-height:1.9;\">رسوبات به مرور زمان روی هم انباشته می‌شوند و لایه‌های رسوبی را می‌سازند. <strong>لایه‌های پایین‌تر، قدیمی‌تر</strong> و لایه‌های بالایی جدیدتر هستند. بنابراین فسیل‌های موجود در لایه‌های پایین‌تر، مربوط به جانداران قدیمی‌تر هستند.</p>\n\n<!-- TAB: نمودار درختی -->\n<h2 style=\"color:#34d399; margin-bottom:15px;\">🌳 نمودار درختی تاریخ زمین</h2>\n<div class=\"xmind-container\">\n    <div class=\"xmind-root\">فسیل</div>\n    <div class=\"xmind-branches\">\n        <div class=\"xmind-branch\"><div class=\"xmind-node\"><strong>تعریف</strong>آثار جانداران گذشته</div></div>\n        <div class=\"xmind-branch\"><div class=\"xmind-node\"><strong>تشکیل</strong>در لایه‌های رسوبی</div></div>\n        <div class=\"xmind-branch\"><div class=\"xmind-node\"><strong>اهمیت</strong>کشف محیط زندگی و غذای جانداران</div></div>\n        <div class=\"xmind-branch\"><div class=\"xmind-node\"><strong>لایه‌ها</strong>لایه پایین = قدیمی‌تر</div></div>\n    </div>\n</div>\n\n<!-- TAB: نکات امتحانی -->\n<h2 style=\"color:#34d399; margin-bottom:15px;\">📝 نکات امتحانی درس چهارم</h2>\n<div style=\"background:rgba(255,255,255,0.04); border:1px solid rgba(255,255,255,0.08); border-radius:14px; padding:16px 20px; margin-bottom:14px;\">\n    <h4 style=\"color:#fbbf24; margin-bottom:8px; font-size:1rem;\">⚠️ نکته ۱: فسیل‌های حشرات</h4>\n    <p style=\"font-size:0.9rem; color:#cbd5e1; line-height:1.8; margin:0;\">با وجود اینکه حشرات تعداد زیادی دارند، فسیل آنها کم است؛ زیرا بدن نرمی دارند و زود از بین می‌روند.</p>\n</div>\n<div style=\"background:rgba(255,255,255,0.04); border:1px solid rgba(255,255,255,0.08); border-radius:14px; padding:16px 20px; margin-bottom:14px;\">\n    <h4 style=\"color:#fbbf24; margin-bottom:8px; font-size:1rem;\">⚠️ نکته ۲: اطلاعات فسیل‌ها</h4>\n    <p style=\"font-size:0.9rem; color:#cbd5e1; line-height:1.8; margin:0;\">از روی فسیل‌ها می‌توان نوع غذا، محل زندگی و تغییرات آب و هوایی گذشته زمین را تشخیص داد.</p>\n</div>\n\n<!-- TAB: آزمون -->\n<h2 style=\"color:#34d399; margin-bottom:15px;\">🧪 آزمون درس چهارم</h2>\n<div style=\"background:rgba(255,255,255,0.04); border:1px solid rgba(255,255,255,0.08); border-radius:14px; padding:20px; margin-bottom:18px;\">\n    <h4 style=\"color:#e2e8f0; margin-bottom:14px;\">۱. فسیل‌ها بیشتر در کدام نوع سنگ‌ها یافت می‌شوند؟</h4>\n    <div style=\"color:#cbd5e1; line-height:2;\">الف) آذرین &nbsp;&nbsp; <strong>ب) رسوبی</strong> &nbsp;&nbsp; ج) دگرگونی</div>\n</div>\n<div style=\"background:rgba(255,255,255,0.04); border:1px solid rgba(255,255,255,0.08); border-radius:14px; padding:20px; margin-bottom:18px;\">\n    <h4 style=\"color:#e2e8f0; margin-bottom:14px;\">۲. در لایه‌های رسوبی، فسیل موجود در لایه پایین‌تر نشان‌دهنده چیست؟</h4>\n    <div style=\"color:#cbd5e1; line-height:2;\">الف) جاندار جدیدتر &nbsp;&nbsp; <strong>ب) جاندار قدیمی‌تر</strong> &nbsp;&nbsp; ج) جاندار بزرگ‌تر</div>\n</div>\n<div style=\"background:rgba(251,191,36,0.15); border-right:4px solid #fbbf24; padding:15px; border-radius:10px; color:#fde68a;\">\n    💡 <strong>پاسخ‌نامه:</strong> ۱ (ب)، ۲ (ب)\n</div>\n\n<!-- TAB: گام به گام -->\n<h2 style=\"color:#34d399; margin-bottom:15px;\">✍️ گام به گام درس چهارم</h2>\n<p style=\"color:#cbd5e1; line-height:1.9;\"><strong>پاسخ جدول صفحه ۳۱ (لایه‌های خاک و فسیل):</strong></p>\n<ul style=\"color:#cbd5e1; line-height:2;\">\n    <li>در تصویر، ۵ لایه دیده می‌شود.</li>\n    <li>در همه لایه‌ها (به جز لایه‌های بدون فسیل) بقایای جانداران دیده می‌شود.</li>\n    <li>باقی‌مانده جاندار در <strong>لایه پایین‌تر، قدیمی‌تر</strong> است.</li>\n</ul>","r":"1nr9hqh"},{"id":"l_1792499825237","title":"5","fullHtml":"<!-- TAB: محتوا -->\n<h2 style=\"color:#34d399; margin-bottom:15px;\">🦴 درس پنجم: حرکت بدن</h2>\n<p style=\"color:#cbd5e1; line-height:1.9;\">بدن انسان برای حرکت کردن به همکاری استخوان‌ها، ماهیچه‌ها و مفصل‌ها نیاز دارد. همچنین مغز و نخاع فرمان‌های لازم برای این حرکات را صادر می‌کنند.</p>\n\n<h3 style=\"color:#6ee7b7; margin-top:20px;\">استخوان‌ها و اسکلت</h3>\n<p style=\"color:#cbd5e1; line-height:1.9;\">مجموع استخوان‌های بدن، <strong>اسکلت</strong> را تشکیل می‌دهند. اسکلت به بدن شکل می‌دهد، از اندام‌های داخلی محافظت می‌کند (مثل جمجمه از مغز و قفسه سینه از قلب و شش‌ها) و به ما امکان حرکت می‌دهد.</p>\n\n<h3 style=\"color:#6ee7b7; margin-top:20px;\">ماهیچه‌ها و مفصل‌ها</h3>\n<p style=\"color:#cbd5e1; line-height:1.9;\">ماهیچه‌ها با کوتاه و بلند شدن، استخوان‌ها را حرکت می‌دهند. ماهیچه‌هایی که روی بازو هستند (مثل ماهیچه‌ی دو سر) با کوتاه شدن، ساعد را بالا می‌کشند. استخوان‌ها در محل‌هایی به نام <strong>مفصل</strong> به هم متصل می‌شوند. مفصل‌ها مانند لولا عمل می‌کنند و به استخوان‌ها اجازه حرکت می‌دهند.</p>\n\n<h3 style=\"color:#6ee7b7; margin-top:20px;\">مغز و نخاع</h3>\n<p style=\"color:#cbd5e1; line-height:1.9;\">دستور حرکت از مغز صادر می‌شود و از طریق <strong>نخاع</strong> و رشته‌های عصبی (اعصاب) به ماهیچه‌ها می‌رسد. مغز و نخاع بسیار حساس هستند و به همین دلیل درون استخوان‌های محکم (جمجمه و ستون مهره‌ها) قرار گرفته‌اند.</p>\n\n<!-- TAB: نمودار درختی -->\n<h2 style=\"color:#34d399; margin-bottom:15px;\">🌳 نمودار درختی حرکت بدن</h2>\n<div class=\"xmind-container\">\n    <div class=\"xmind-root\">حرکت بدن</div>\n    <div class=\"xmind-branches\">\n        <div class=\"xmind-branch\"><div class=\"xmind-node\"><strong>اسکلت</strong>شکل‌دهی و محافظت</div></div>\n        <div class=\"xmind-branch\"><div class=\"xmind-node\"><strong>ماهیچه‌ها</strong>کوتاه و بلند شدن</div></div>\n        <div class=\"xmind-branch\"><div class=\"xmind-node\"><strong>مفصل‌ها</strong>محل اتصال استخوان‌ها</div></div>\n        <div class=\"xmind-branch\"><div class=\"xmind-node\"><strong>مغز و نخاع</strong>صدور فرمان حرکت</div></div>\n    </div>\n</div>\n\n<!-- TAB: نکات امتحانی -->\n<h2 style=\"color:#34d399; margin-bottom:15px;\">📝 نکات امتحانی درس پنجم</h2>\n<div style=\"background:rgba(255,255,255,0.04); border:1px solid rgba(255,255,255,0.08); border-radius:14px; padding:16px 20px; margin-bottom:14px;\">\n    <h4 style=\"color:#fbbf24; margin-bottom:8px; font-size:1rem;\">⚠️ نکته ۱: نقش ماهیچه‌ها</h4>\n    <p style=\"font-size:0.9rem; color:#cbd5e1; line-height:1.8; margin:0;\">ماهیچه‌ها فقط می‌توانند خودشان را جمع کنند (کوتاه شوند)، بنابراین برای خم و راست کردن یک عضو، به دو ماهیچه مخالف هم نیاز است (مثل ماهیچه روی بازو و پشت بازو).</p>\n</div>\n<div style=\"background:rgba(255,255,255,0.04); border:1px solid rgba(255,255,255,0.08); border-radius:14px; padding:16px 20px; margin-bottom:14px;\">\n    <h4 style=\"color:#fbbf24; margin-bottom:8px; font-size:1rem;\">⚠️ نکته ۲: استخوان زنده است</h4>\n    <p style=\"font-size:0.9rem; color:#cbd5e1; line-height:1.8; margin:0;\">استخوان‌ها بافت زنده هستند و رشد می‌کنند. خوردن لبنیات و قرار گرفتن در معرض نور خورشید برای استحکام آن‌ها ضروری است.</p>\n</div>\n\n<!-- TAB: آزمون -->\n<h2 style=\"color:#34d399; margin-bottom:15px;\">🧪 آزمون درس پنجم</h2>\n<div style=\"background:rgba(255,255,255,0.04); border:1px solid rgba(255,255,255,0.08); border-radius:14px; padding:20px; margin-bottom:18px;\">\n    <h4 style=\"color:#e2e8f0; margin-bottom:14px;\">۱. کدام‌یک از اندام‌های زیر درون جمجمه قرار دارد؟</h4>\n    <div style=\"color:#cbd5e1; line-height:2;\">الف) قلب &nbsp;&nbsp; <strong>ب) مغز</strong> &nbsp;&nbsp; ج) نخاع &nbsp;&nbsp; د) شش‌ها</div>\n</div>\n<div style=\"background:rgba(255,255,255,0.04); border:1px solid rgba(255,255,255,0.08); border-radius:14px; padding:20px; margin-bottom:18px;\">\n    <h4 style=\"color:#e2e8f0; margin-bottom:14px;\">۲. محل اتصال دو استخوان به یکدیگر چه نام دارد؟</h4>\n    <div style=\"color:#cbd5e1; line-height:2;\">الف) ماهیچه &nbsp;&nbsp; <strong>ب) مفصل</strong> &nbsp;&nbsp; ج) عصب</div>\n</div>\n<div style=\"background:rgba(251,191,36,0.15); border-right:4px solid #fbbf24; padding:15px; border-radius:10px; color:#fde68a;\">\n    💡 <strong>پاسخ‌نامه:</strong> ۱ (ب)، ۲ (ب)\n</div>\n\n<!-- TAB: گام به گام -->\n<h2 style=\"color:#34d399; margin-bottom:15px;\">✍️ گام به گام درس پنجم</h2>\n<p style=\"color:#cbd5e1; line-height:1.9;\"><strong>پاسخ فعالیت صفحه ۴۸ (مدل حرکت):</strong> وقتی نخ قرمز را می‌کشیم، مقوای زرد (ساعد) به سمت بالا حرکت می‌کند. وقتی نخ آبی را می‌کشیم، مقوای زرد به سمت پایین می‌رود. این مدل نشان می‌دهد که چگونه ماهیچه‌ها با کوتاه شدن، استخوان‌ها را حرکت می‌دهند.</p>","r":"x0w5ct"},{"id":"l_1792499827446","title":"6","fullHtml":"<!-- TAB: محتوا -->\n<h2 style=\"color:#34d399; margin-bottom:15px;\">👁️ درس ششم: چه خبر؟ (۱)</h2>\n<p style=\"color:#cbd5e1; line-height:1.9;\">ما با اندام‌های حسی خود (چشم، گوش، بینی، زبان و پوست) اطلاعاتی از محیط اطراف دریافت می‌کنیم و به مغز می‌فرستیم. در این درس با بینایی و شنوایی آشنا می‌شویم.</p>\n\n<h3 style=\"color:#6ee7b7; margin-top:20px;\">چشم و بینایی</h3>\n<ul style=\"color:#cbd5e1; line-height:2; padding-right:20px;\">\n    <li><strong>قرنیه:</strong> پرده شفاف روی چشم.</li>\n    <li><strong>عنبیه:</strong> بخش رنگی چشم.</li>\n    <li><strong>مردمک:</strong> سوراخ وسط عنبیه که نور از آن وارد می‌شود.</li>\n    <li><strong>عدسی:</strong> نور را روی شبکیه جمع می‌کند.</li>\n    <li><strong>شبکیه:</strong> پرده‌ای در انتهای چشم که سلول‌های گیرنده نور در آن قرار دارند.</li>\n    <li><strong>عصب بینایی:</strong> پیام‌های نوری را از شبکیه به مغز می‌برد.</li>\n</ul>\n\n<h3 style=\"color:#6ee7b7; margin-top:20px;\">گوش و شنوایی</h3>\n<p style=\"color:#cbd5e1; line-height:1.9;\">صداها ابتدا وارد لاله گوش می‌شوند، از مجرای شنوایی عبور می‌کنند و به <strong>پرده گوش</strong> می‌رسند. پرده گوش را می‌لرزانند. این لرزش به استخوان‌های کوچک گوش منتقل شده و به بخش حلزونی می‌رسد. عصب شنوایی پیام را به مغز می‌فرستد.</p>\n\n<!-- TAB: نمودار درختی -->\n<h2 style=\"color:#34d399; margin-bottom:15px;\">🌳 نمودار درختی حواس (بینایی و شنوایی)</h2>\n<div class=\"xmind-container\">\n    <div class=\"xmind-root\">حواس</div>\n    <div class=\"xmind-branches\">\n        <div class=\"xmind-branch\"><div class=\"xmind-node\"><strong>چشم</strong>عدسی، شبکیه، عصب بینایی</div></div>\n        <div class=\"xmind-branch\"><div class=\"xmind-node\"><strong>گوش</strong>لاله، پرده، حلزون، عصب شنوایی</div></div>\n    </div>\n</div>\n\n<!-- TAB: نکات امتحانی -->\n<h2 style=\"color:#34d399; margin-bottom:15px;\">📝 نکات امتحانی درس ششم</h2>\n<div style=\"background:rgba(255,255,255,0.04); border:1px solid rgba(255,255,255,0.08); border-radius:14px; padding:16px 20px; margin-bottom:14px;\">\n    <h4 style=\"color:#fbbf24; margin-bottom:8px; font-size:1rem;\">⚠️ نکته ۱: عینک</h4>\n    <p style=\"font-size:0.9rem; color:#cbd5e1; line-height:1.8; margin:0;\">اگر عدسی چشم نتواند نور را دقیقاً روی شبکیه جمع کند، تصویر تار می‌شود. عینک با اصلاح مسیر نور به چشم کمک می‌کند.</p>\n</div>\n<div style=\"background:rgba(255,255,255,0.04); border:1px solid rgba(255,255,255,0.08); border-radius:14px; padding:16px 20px; margin-bottom:14px;\">\n    <h4 style=\"color:#fbbf24; margin-bottom:8px; font-size:1rem;\">⚠️ نکته ۲: مراقبت از گوش</h4>\n    <p style=\"font-size:0.9rem; color:#cbd5e1; line-height:1.8; margin:0;\">هرگز اجسام نوک‌تیز را در گوش فرو نکنید و از صداهای بسیار بلند دوری کنید، زیرا به پرده گوش و سلول‌های شنوایی آسیب می‌زند.</p>\n</div>\n\n<!-- TAB: آزمون -->\n<h2 style=\"color:#34d399; margin-bottom:15px;\">🧪 آزمون درس ششم</h2>\n<div style=\"background:rgba(255,255,255,0.04); border:1px solid rgba(255,255,255,0.08); border-radius:14px; padding:20px; margin-bottom:18px;\">\n    <h4 style=\"color:#e2e8f0; margin-bottom:14px;\">۱. کدام بخش چشم، رنگ چشم را تعیین می‌کند؟</h4>\n    <div style=\"color:#cbd5e1; line-height:2;\">الف) مردمک &nbsp;&nbsp; <strong>ب) عنبیه</strong> &nbsp;&nbsp; ج) شبکیه &nbsp;&nbsp; د) قرنیه</div>\n</div>\n<div style=\"background:rgba(255,255,255,0.04); border:1px solid rgba(255,255,255,0.08); border-radius:14px; padding:20px; margin-bottom:18px;\">\n    <h4 style=\"color:#e2e8f0; margin-bottom:14px;\">۲. پیام‌های شنوایی توسط کدام بخش به مغز می‌رود؟</h4>\n    <div style=\"color:#cbd5e1; line-height:2;\">الف) پرده گوش &nbsp;&nbsp; ب) مجرای شنوایی &nbsp;&nbsp; <strong>ج) عصب شنوایی</strong></div>\n</div>\n<div style=\"background:rgba(251,191,36,0.15); border-right:4px solid #fbbf24; padding:15px; border-radius:10px; color:#fde68a;\">\n    💡 <strong>پاسخ‌نامه:</strong> ۱ (ب)، ۲ (ج)\n</div>\n\n<!-- TAB: گام به گام -->\n<h2 style=\"color:#34d399; margin-bottom:15px;\">✍️ گام به گام درس ششم</h2>\n<p style=\"color:#cbd5e1; line-height:1.9;\"><strong>پاسخ فعالیت صفحه ۵۶ (فاصله مناسب برای خواندن):</strong> افراد نزدیک‌بین اجسام نزدیک را خوب می‌بینند ولی اجسام دور را تار می‌بینند و به عینک نیاز دارند. افراد دوربین برعکس عمل می‌کنند.</p>","r":"a4n0g4"},{"id":"l_1792499829260","title":"7","fullHtml":"<!-- TAB: محتوا -->\n<h2 style=\"color:#34d399; margin-bottom:15px;\">👅 درس هفتم: چه خبر؟ (۲)</h2>\n<p style=\"color:#cbd5e1; line-height:1.9;\">در این درس با حواس چشایی (زبان)، بویایی (بینی) و لامسه (پوست) آشنا می‌شویم.</p>\n\n<h3 style=\"color:#6ee7b7; margin-top:20px;\">چشایی و بویایی</h3>\n<p style=\"color:#cbd5e1; line-height:1.9;\">روی زبان برجستگی‌هایی وجود دارد که مزه‌ها را دریافت می‌کنند. برای تشخیص کامل مزه‌ها، حس بویایی هم به ما کمک می‌کند. وقتی بینی ما بسته است، طعم غذاها را کمتر تشخیص می‌دهیم. سلول‌های گیرنده بویایی در بالای بینی قرار دارند.</p>\n\n<h3 style=\"color:#6ee7b7; margin-top:20px;\">لامسه (پوست)</h3>\n<p style=\"color:#cbd5e1; line-height:1.9;\">پوست بزرگ‌ترین اندام بدن است. در پوست گیرنده‌های حسی مختلفی برای لمس، دما (گرما و سرما) و درد وجود دارد. نوک انگشتان و لب‌ها بیشترین تعداد گیرنده لمسی را دارند و به همین دلیل حساس‌ترند.</p>\n\n<!-- TAB: نمودار درختی -->\n<h2 style=\"color:#34d399; margin-bottom:15px;\">🌳 نمودار درختی چشایی، بویایی، لامسه</h2>\n<div class=\"xmind-container\">\n    <div class=\"xmind-root\">حواس دیگر</div>\n    <div class=\"xmind-branches\">\n        <div class=\"xmind-branch\"><div class=\"xmind-node\"><strong>چشایی</strong>برجستگی‌های زبان</div></div>\n        <div class=\"xmind-branch\"><div class=\"xmind-node\"><strong>بویایی</strong>گیرنده‌های بینی</div></div>\n        <div class=\"xmind-branch\"><div class=\"xmind-node\"><strong>لامسه</strong>گیرنده‌های پوست (لمس، دما، درد)</div></div>\n    </div>\n</div>\n\n<!-- TAB: نکات امتحانی -->\n<h2 style=\"color:#34d399; margin-bottom:15px;\">📝 نکات امتحانی درس هفتم</h2>\n<div style=\"background:rgba(255,255,255,0.04); border:1px solid rgba(255,255,255,0.08); border-radius:14px; padding:16px 20px; margin-bottom:14px;\">\n    <h4 style=\"color:#fbbf24; margin-bottom:8px; font-size:1rem;\">⚠️ نکته ۱: ارتباط بو و مزه</h4>\n    <p style=\"font-size:0.9rem; color:#cbd5e1; line-height:1.8; margin:0;\">اگر بینی خود را بگیریم، تشخیص مزه بعضی غذاها (مثل سیب و سیب‌زمینی) سخت می‌شود.</p>\n</div>\n<div style=\"background:rgba(255,255,255,0.04); border:1px solid rgba(255,255,255,0.08); border-radius:14px; padding:16px 20px; margin-bottom:14px;\">\n    <h4 style=\"color:#fbbf24; margin-bottom:8px; font-size:1rem;\">⚠️ نکته ۲: حساسیت پوست</h4>\n    <p style=\"font-size:0.9rem; color:#cbd5e1; line-height:1.8; margin:0;\">هرچه گیرنده‌های لمسی در یک نقطه از پوست بیشتر باشد، آن نقطه حساس‌تر است (مثل نوک انگشتان).</p>\n</div>\n\n<!-- TAB: آزمون -->\n<h2 style=\"color:#34d399; margin-bottom:15px;\">🧪 آزمون درس هفتم</h2>\n<div style=\"background:rgba(255,255,255,0.04); border:1px solid rgba(255,255,255,0.08); border-radius:14px; padding:20px; margin-bottom:18px;\">\n    <h4 style=\"color:#e2e8f0; margin-bottom:14px;\">۱. مزه غذاها توسط کدام قسمت دریافت می‌شود؟</h4>\n    <div style=\"color:#cbd5e1; line-height:2;\">الف) دندان‌ها &nbsp;&nbsp; <strong>ب) برجستگی‌های زبان</strong> &nbsp;&nbsp; ج) لثه‌ها</div>\n</div>\n<div style=\"background:rgba(255,255,255,0.04); border:1px solid rgba(255,255,255,0.08); border-radius:14px; padding:20px; margin-bottom:18px;\">\n    <h4 style=\"color:#e2e8f0; margin-bottom:14px;\">۲. کدام حس به تشخیص بهتر مزه غذا کمک می‌کند؟</h4>\n    <div style=\"color:#cbd5e1; line-height:2;\">الف) بینایی &nbsp;&nbsp; ب) شنوایی &nbsp;&nbsp; <strong>ج) بویایی</strong></div>\n</div>\n<div style=\"background:rgba(251,191,36,0.15); border-right:4px solid #fbbf24; padding:15px; border-radius:10px; color:#fde68a;\">\n    💡 <strong>پاسخ‌نامه:</strong> ۱ (ب)، ۲ (ج)\n</div>\n\n<!-- TAB: گام به گام -->\n<h2 style=\"color:#34d399; margin-bottom:15px;\">✍️ گام به گام درس هفتم</h2>\n<p style=\"color:#cbd5e1; line-height:1.9;\"><strong>نتیجه آزمایش صفحه ۶۴ (مزه و بو):</strong> وقتی بینی بسته است، تشخیص مزه‌ها سخت‌تر می‌شود. این آزمایش ثابت می‌کند که حس بویایی و چشایی با هم در ارتباط هستند.</p>","r":"1kypuh0"},{"id":"l_1792499831260","title":"8","fullHtml":"<!-- TAB: محتوا -->\n<h2 style=\"color:#34d399; margin-bottom:15px;\">⚖️ درس هشتم: کارها آسان می‌شود (۱)</h2>\n<p style=\"color:#cbd5e1; line-height:1.9;\">انسان برای انجام راحت‌تر کارها از ابزارهایی استفاده می‌کند. به این ابزارها <strong>ماشین‌های ساده</strong> می‌گویند. در این درس با اهرم‌ها آشنا می‌شویم.</p>\n\n<h3 style=\"color:#6ee7b7; margin-top:20px;\">اهرم چیست؟</h3>\n<p style=\"color:#cbd5e1; line-height:1.9;\">اهرم یک میله است که روی یک تکیه‌گاه قرار می‌گیرد و برای بلند کردن اجسام استفاده می‌شود (مثل الاکلنگ). هر اهرم سه بخش دارد:</p>\n<ul style=\"color:#cbd5e1; line-height:2; padding-right:20px;\">\n    <li><strong>تکیه‌گاه:</strong> نقطه‌ای که اهرم روی آن می‌چرخد.</li>\n    <li><strong>نیرو (نیروی محرک):</strong> محلی که ما نیرو وارد می‌کنیم.</li>\n    <li><strong>جسم (بار):</strong> محلی که جسم قرار دارد.</li>\n</ul>\n<p style=\"color:#cbd5e1; line-height:1.9;\">در یک اهرم، هرچه جسم به تکیه‌گاه نزدیک‌تر باشد، بلند کردن آن راحت‌تر است و به نیروی کمتری نیاز دارد.</p>\n\n<!-- TAB: نمودار درختی -->\n<h2 style=\"color:#34d399; margin-bottom:15px;\">🌳 نمودار درختی اهرم‌ها</h2>\n<div class=\"xmind-container\">\n    <div class=\"xmind-root\">اهرم</div>\n    <div class=\"xmind-branches\">\n        <div class=\"xmind-branch\"><div class=\"xmind-node\"><strong>اجزا</strong>تکیه‌گاه، نیرو، جسم</div></div>\n        <div class=\"xmind-branch\"><div class=\"xmind-node\"><strong>قانون</strong>جسم نزدیک‌تر به تکیه‌گاه = نیروی کمتر</div></div>\n        <div class=\"xmind-branch\"><div class=\"xmind-node\"><strong>نمونه‌ها</strong>الاکلنگ، قیچی، فرغون، انبردست</div></div>\n    </div>\n</div>\n\n<!-- TAB: نکات امتحانی -->\n<h2 style=\"color:#34d399; margin-bottom:15px;\">📝 نکات امتحانی درس هشتم</h2>\n<div style=\"background:rgba(255,255,255,0.04); border:1px solid rgba(255,255,255,0.08); border-radius:14px; padding:16px 20px; margin-bottom:14px;\">\n    <h4 style=\"color:#fbbf24; margin-bottom:8px; font-size:1rem;\">⚠️ نکته ۱: انواع اهرم</h4>\n    <p style=\"font-size:0.9rem; color:#cbd5e1; line-height:1.8; margin:0;\">در برخی اهرم‌ها (مثل قیچی) تکیه‌گاه وسط است. در برخی (مثل فرغون) جسم وسط است. در برخی (مثل انبر و موچین) نیرو وسط است.</p>\n</div>\n\n<!-- TAB: آزمون -->\n<h2 style=\"color:#34d399; margin-bottom:15px;\">🧪 آزمون درس هشتم</h2>\n<div style=\"background:rgba(255,255,255,0.04); border:1px solid rgba(255,255,255,0.08); border-radius:14px; padding:20px; margin-bottom:18px;\">\n    <h4 style=\"color:#e2e8f0; margin-bottom:14px;\">۱. در الاکلنگ، نقطه‌ای که میله روی آن قرار دارد چه نام دارد؟</h4>\n    <div style=\"color:#cbd5e1; line-height:2;\">الف) نیرو &nbsp;&nbsp; ب) جسم &nbsp;&nbsp; <strong>ج) تکیه‌گاه</strong></div>\n</div>\n<div style=\"background:rgba(255,255,255,0.04); border:1px solid rgba(255,255,255,0.08); border-radius:14px; padding:20px; margin-bottom:18px;\">\n    <h4 style=\"color:#e2e8f0; margin-bottom:14px;\">۲. برای بلند کردن یک سنگین با اهرم، کدام حالت راحت‌تر است؟</h4>\n    <div style=\"color:#cbd5e1; line-height:2;\">الف) جسم دور از تکیه‌گاه باشد &nbsp;&nbsp; <strong>ب) جسم نزدیک تکیه‌گاه باشد</strong> &nbsp;&nbsp; ج) نیرو نزدیک تکیه‌گاه باشد</div>\n</div>\n<div style=\"background:rgba(251,191,36,0.15); border-right:4px solid #fbbf24; padding:15px; border-radius:10px; color:#fde68a;\">\n    💡 <strong>پاسخ‌نامه:</strong> ۱ (ج)، ۲ (ب)\n</div>\n\n<!-- TAB: گام به گام -->\n<h2 style=\"color:#34d399; margin-bottom:15px;\">✍️ گام به گام درس هشتم</h2>\n<p style=\"color:#cbd5e1; line-height:1.9;\"><strong>پاسخ جدول صفحه ۷۵ (طبقه‌بندی اهرم‌ها):</strong></p>\n<ul style=\"color:#cbd5e1; line-height:2;\">\n    <li><strong>تکیه‌گاه بین جسم و نیرو:</strong> قیچی، الاکلنگ، منگنه.</li>\n    <li><strong>جسم بین تکیه‌گاه و نیرو:</strong> فرغون.</li>\n    <li><strong>نیرو بین جسم و تکیه‌گاه:</strong> موچین، انبردست، جورقزن.</li>\n</ul>","r":"i9way8"},{"id":"l_1792499833277","title":"9","fullHtml":"<!-- TAB: محتوا -->\n<h2 style=\"color:#34d399; margin-bottom:15px;\">🛠️ درس نهم: کارها آسان می‌شود (۲)</h2>\n<p style=\"color:#cbd5e1; line-height:1.9;\">علاوه بر اهرم، ماشین‌های ساده دیگری نیز وجود دارند که به ما در انجام کارها کمک می‌کنند.</p>\n\n<h3 style=\"color:#6ee7b7; margin-top:20px;\">سطح شیب‌دار</h3>\n<p style=\"color:#cbd5e1; line-height:1.9;\">به جای بلند کردن اجسام به صورت عمودی، می‌توانیم آن‌ها را روی یک سطح شیب‌دار (مثل رمپ یا نردبان) به بالا ببریم. سطح شیب‌دار <strong>نیروی لازم برای بالا بردن اجسام را کاهش می‌دهد</strong>، اما مسافت طی شده بیشتر می‌شود.</p>\n\n<h3 style=\"color:#6ee7b7; margin-top:20px;\">گوه</h3>\n<p style=\"color:#cbd5e1; line-height:1.9;\">گوه از دو سطح شیب‌دار که از پشت به هم چسبیده‌اند تشکیل شده است (مثل لبه چاقو، تبر، میخ). از گوه برای بریدن و شکافتن اجسام استفاده می‌شود.</p>\n\n<h3 style=\"color:#6ee7b7; margin-top:20px;\">پیچ، قرقره و چرخ و محور</h3>\n<ul style=\"color:#cbd5e1; line-height:2; padding-right:20px;\">\n    <li><strong>پیچ:</strong> در واقع یک سطح شیب‌دار است که به دور یک استوانه پیچیده شده است. پیچ‌ها برای محکم کردن قطعات به هم استفاده می‌شوند.</li>\n    <li><strong>قرقره:</strong> چرخی است که یک طناب از روی آن عبور می‌کند. قرقره برای بالا کشیدن اجسام (مثل پرچم یا تور ماهیگیری) به ما کمک می‌کند.</li>\n    <li><strong>چرخ و محور:</strong> از یک چرخ و یک محور تشکیل شده است (مثل دستگیره در یا فرمان ماشین).</li>\n</ul>\n\n<!-- TAB: نمودار درختی -->\n<h2 style=\"color:#34d399; margin-bottom:15px;\">🌳 نمودار درختی ماشین‌های ساده</h2>\n<div class=\"xmind-container\">\n    <div class=\"xmind-root\">ماشین‌های ساده</div>\n    <div class=\"xmind-branches\">\n        <div class=\"xmind-branch\"><div class=\"xmind-node\"><strong>اهرم</strong>تکیه‌گاه، نیرو، جسم</div></div>\n        <div class=\"xmind-branch\"><div class=\"xmind-node\"><strong>سطح شیب‌دار</strong>کاهش نیرو</div></div>\n        <div class=\"xmind-branch\"><div class=\"xmind-node\"><strong>گوه</strong>بریدن و شکافتن</div></div>\n        <div class=\"xmind-branch\"><div class=\"xmind-node\"><strong>پیچ</strong>سطح شیب‌دار پیچیده</div></div>\n        <div class=\"xmind-branch\"><div class=\"xmind-node\"><strong>قرقره</strong>بالا کشیدن اجسام</div></div>\n        <div class=\"xmind-branch\"><div class=\"xmind-node\"><strong>چرخ و محور</strong>دستگیره، فرمان</div></div>\n    </div>\n</div>\n\n<!-- TAB: نکات امتحانی -->\n<h2 style=\"color:#34d399; margin-bottom:15px;\">📝 نکات امتحانی درس نهم</h2>\n<div style=\"background:rgba(255,255,255,0.04); border:1px solid rgba(255,255,255,0.08); border-radius:14px; padding:16px 20px; margin-bottom:14px;\">\n    <h4 style=\"color:#fbbf24; margin-bottom:8px; font-size:1rem;\">⚠️ نکته ۱: سطح شیب‌دار</h4>\n    <p style=\"font-size:0.9rem; color:#cbd5e1; line-height:1.8; margin:0;\">سطح شیب‌دار نیروی لازم برای بالا بردن را کم می‌کند، اما چون مسیر طولانی‌تر می‌شود، کار کل تغییر نمی‌کند.</p>\n</div>\n<div style=\"background:rgba(255,255,255,0.04); border:1px solid rgba(255,255,255,0.08); border-radius:14px; padding:16px 20px; margin-bottom:14px;\">\n    <h4 style=\"color:#fbbf24; margin-bottom:8px; font-size:1rem;\">⚠️ نکته ۲: گوه</h4>\n    <p style=\"font-size:0.9rem; color:#cbd5e1; line-height:1.8; margin:0;\">دندان‌های انسان و حیوانات گوشت‌خوار نیز مانند گوه عمل می‌کنند.</p>\n</div>\n\n<!-- TAB: آزمون -->\n<h2 style=\"color:#34d399; margin-bottom:15px;\">🧪 آزمون درس نهم</h2>\n<div style=\"background:rgba(255,255,255,0.04); border:1px solid rgba(255,255,255,0.08); border-radius:14px; padding:20px; margin-bottom:18px;\">\n    <h4 style=\"color:#e2e8f0; margin-bottom:14px;\">۱. لبه‌ی چاقو و تبر جزو کدام دسته از ماشین‌های ساده هستند؟</h4>\n    <div style=\"color:#cbd5e1; line-height:2;\">الف) اهرم &nbsp;&nbsp; ب) پیچ &nbsp;&nbsp; <strong>ج) گوه</strong> &nbsp;&nbsp; د) قرقره</div>\n</div>\n<div style=\"background:rgba(255,255,255,0.04); border:1px solid rgba(255,255,255,0.08); border-radius:14px; padding:20px; margin-bottom:18px;\">\n    <h4 style=\"color:#e2e8f0; margin-bottom:14px;\">۲. برای بالا کشیدن پرچم از چه وسیله‌ای استفاده می‌شود؟</h4>\n    <div style=\"color:#cbd5e1; line-height:2;\">الف) سطح شیب‌دار &nbsp;&nbsp; <strong>ب) قرقره</strong> &nbsp;&nbsp; ج) گوه</div>\n</div>\n<div style=\"background:rgba(251,191,36,0.15); border-right:4px solid #fbbf24; padding:15px; border-radius:10px; color:#fde68a;\">\n    💡 <strong>پاسخ‌نامه:</strong> ۱ (ج)، ۲ (ب)\n</div>\n\n<!-- TAB: گام به گام -->\n<h2 style=\"color:#34d399; margin-bottom:15px;\">✍️ گام به گام درس نهم</h2>\n<p style=\"color:#cbd5e1; line-height:1.9;\"><strong>نتیجه آزمایش صفحه ۸۰ (سطح شیب‌دار):</strong> با استفاده از سطح شیب‌دار، کشش کمتری به کش وارد می‌شود (طول کش کمتر است) نسبت به وقتی که کتاب‌ها را به طور عمودی بالا می‌بریم. هرچه شیب کمتر باشد (ارتفاع کمتر)، نیروی کمتری لازم است.</p>","r":"cx1suu"},{"id":"l_1792499835621","title":"10","fullHtml":"<!-- TAB: محتوا -->\n<h2 style=\"color:#34d399; margin-bottom:15px;\">🌱 درس دهم: خاک با ارزش</h2>\n<p style=\"color:#cbd5e1; line-height:1.9;\">خاک یکی از منابع طبیعی بسیار مهم است که در طبیعت به کندی تشکیل می‌شود. خاک از خرد شدن سنگ‌ها و تجزیه بقایای گیاهان و جانوران به وجود می‌آید.</p>\n\n<h3 style=\"color:#6ee7b7; margin-top:20px;\">عوامل خرد شدن سنگ‌ها</h3>\n<ul style=\"color:#cbd5e1; line-height:2; padding-right:20px;\">\n    <li><strong>عوامل فیزیکی:</strong> باد، آب، تغییرات دما (گرما و سرما) و رشد ریشه گیاهان در شکاف سنگ‌ها.</li>\n    <li><strong>عوامل شیمیایی:</strong> حل شدن بعضی از مواد سنگ‌ها در آب.</li>\n</ul>\n\n<h3 style=\"color:#6ee7b7; margin-top:20px;\">انواع خاک</h3>\n<p style=\"color:#cbd5e1; line-height:1.9;\">خاک‌ها از نظر اندازه ذرات به سه دسته تقسیم می‌شوند:</p>\n<ul style=\"color:#cbd5e1; line-height:2; padding-right:20px;\">\n    <li><strong>خاک شنی (ماسه):</strong> ذرات درشت، آب را سریع از خود عبور می‌دهد.</li>\n    <li><strong>خاک رسی:</strong> ذرات بسیار ریز، آب را در خود نگه می‌دارد.</li>\n    <li><strong>خاک باغچه (خاک هوموسی):</strong> مخلوطی از ماسه، رس و بقایای گیاهان و جانوران. بهترین خاک برای کشاورزی و رشد گیاهان است.</li>\n</ul>\n\n<h3 style=\"color:#6ee7b7; margin-top:20px;\">فرسایش خاک</h3>\n<p style=\"color:#cbd5e1; line-height:1.9;\">جابه‌جا شدن خاک توسط آب و باد را <strong>فرسایش</strong> می‌گویند. عواملی مانند قطع درختان، چرای بی‌رویه دام‌ها و شخم زدن در جهت شیب زمین، باعث فرسایش سریع‌تر خاک می‌شوند.</p>\n\n<!-- TAB: نمودار درختی -->\n<h2 style=\"color:#34d399; margin-bottom:15px;\">🌳 نمودار درختی خاک</h2>\n<div class=\"xmind-container\">\n    <div class=\"xmind-root\">خاک</div>\n    <div class=\"xmind-branches\">\n        <div class=\"xmind-branch\"><div class=\"xmind-node\"><strong>تشکیل</strong>خرد شدن سنگ + بقایای گیاهان</div></div>\n        <div class=\"xmind-branch\"><div class=\"xmind-node\"><strong>انواع</strong>شنی، رسی، باغچه</div></div>\n        <div class=\"xmind-branch\"><div class=\"xmind-node\"><strong>نفوذ آب</strong>شنی (سریع)، رسی (کند)</div></div>\n        <div class=\"xmind-branch\"><div class=\"xmind-node\"><strong>فرسایش</strong>جابه‌جایی توسط آب و باد</div></div>\n    </div>\n</div>\n\n<!-- TAB: نکات امتحانی -->\n<h2 style=\"color:#34d399; margin-bottom:15px;\">📝 نکات امتحانی درس دهم</h2>\n<div style=\"background:rgba(255,255,255,0.04); border:1px solid rgba(255,255,255,0.08); border-radius:14px; padding:16px 20px; margin-bottom:14px;\">\n    <h4 style=\"color:#fbbf24; margin-bottom:8px; font-size:1rem;\">⚠️ نکته ۱: تشکیل خاک</h4>\n    <p style=\"font-size:0.9rem; color:#cbd5e1; line-height:1.8; margin:0;\">تشکیل خاک بسیار کند است. برای تشکیل لایه‌ای خاک به ضخامت ۱ سانتی‌متر، ممکن است صدها سال زمان لازم باشد.</p>\n</div>\n<div style=\"background:rgba(255,255,255,0.04); border:1px solid rgba(255,255,255,0.08); border-radius:14px; padding:16px 20px; margin-bottom:14px;\">\n    <h4 style=\"color:#fbbf24; margin-bottom:8px; font-size:1rem;\">⚠️ نکته ۲: حفظ خاک</h4>\n    <p style=\"font-size:0.9rem; color:#cbd5e1; line-height:1.8; margin:0;\">کاشت درخت، ایجاد تراس در زمین‌های شیب‌دار و جلوگیری از چرای بی‌رویه دام‌ها از راه‌های جلوگیری از فرسایش خاک است.</p>\n</div>\n\n<!-- TAB: آزمون -->\n<h2 style=\"color:#34d399; margin-bottom:15px;\">🧪 آزمون درس دهم</h2>\n<div style=\"background:rgba(255,255,255,0.04); border:1px solid rgba(255,255,255,0.08); border-radius:14px; padding:20px; margin-bottom:18px;\">\n    <h4 style=\"color:#e2e8f0; margin-bottom:14px;\">۱. در کدام نوع خاک، آب سریع‌تر نفوذ می‌کند؟</h4>\n    <div style=\"color:#cbd5e1; line-height:2;\">الف) خاک رسی &nbsp;&nbsp; <strong>ب) خاک شنی</strong> &nbsp;&nbsp; ج) خاک باغچه</div>\n</div>\n<div style=\"background:rgba(255,255,255,0.04); border:1px solid rgba(255,255,255,0.08); border-radius:14px; padding:20px; margin-bottom:18px;\">\n    <h4 style=\"color:#e2e8f0; margin-bottom:14px;\">۲. کدام خاک برای کشاورزی مناسب‌تر است؟</h4>\n    <div style=\"color:#cbd5e1; line-height:2;\">الف) شنی &nbsp;&nbsp; ب) رسی &nbsp;&nbsp; <strong>ج) باغچه (هوموسی)</strong></div>\n</div>\n<div style=\"background:rgba(251,191,36,0.15); border-right:4px solid #fbbf24; padding:15px; border-radius:10px; color:#fde68a;\">\n    💡 <strong>پاسخ‌نامه:</strong> ۱ (ب)، ۲ (ج)\n</div>\n\n<!-- TAB: گام به گام -->\n<h2 style=\"color:#34d399; margin-bottom:15px;\">✍️ گام به گام درس دهم</h2>\n<p style=\"color:#cbd5e1; line-height:1.9;\"><strong>پاسخ فعالیت صفحه ۹۲ (نفوذ آب در خاک):</strong> در خاک شنی، آب سریع‌تر فرو می‌رود. در خاک رسی، آب دیرتر فرو می‌رود و مدت بیشتری در آن باقی می‌ماند. خاک باغچه حالت تعادل دارد و برای گیاهان بهترین است.</p>","r":"npagl"},{"id":"l_1792499837637","title":"11","fullHtml":"<!-- TAB: محتوا -->\n<h2 style=\"color:#34d399; margin-bottom:15px;\">🌻 درس یازدهم: بکارید و بخورید</h2>\n<p style=\"color:#cbd5e1; line-height:1.9;\">گیاهان برای رشد و زنده ماندن، به شرایط مناسبی نیاز دارند. مهم‌ترین نیازهای گیاهان عبارتند از: نور، آب، هوا و خاک مناسب.</p>\n\n<h3 style=\"color:#6ee7b7; margin-top:20px;\">آب و گیاه</h3>\n<p style=\"color:#cbd5e1; line-height:1.9;\">گیاهان برای رشد به آب نیاز دارند، اما مقدار و نوع آب مهم است. آبیاری بیش از حد باعث خفگی ریشه می‌شود. آب شور برای بیشتر گیاهان مناسب نیست و باعث پژمردگی یا از بین رفتن آن‌ها می‌شود.</p>\n\n<h3 style=\"color:#6ee7b7; margin-top:20px;\">خاک و هوا و نور</h3>\n<ul style=\"color:#cbd5e1; line-height:2; padding-right:20px;\">\n    <li><strong>خاک:</strong> خاک باغچه (حاوی مواد غذایی) بهترین رشد را برای گیاه به همراه دارد.</li>\n    <li><strong>هوا:</strong> ریشه‌های گیاه نیز مانند برگ‌ها برای تنفس به هوا (اکسیژن) نیاز دارند. خاک سفت و فشرده مانع رسیدن هوا به ریشه می‌شود.</li>\n    <li><strong>نور:</strong> گیاهان برای ساختن غذای خود (فتوسنتز) به نور خورشید نیاز دارند. اگر به گیاه نور نرسد، برگ‌هایش زرد می‌شوند و رشد نمی‌کند.</li>\n</ul>\n\n<!-- TAB: نمودار درختی -->\n<h2 style=\"color:#34d399; margin-bottom:15px;\">🌳 نمودار درختی نیازهای گیاه</h2>\n<div class=\"xmind-container\">\n    <div class=\"xmind-root\">نیازهای گیاه</div>\n    <div class=\"xmind-branches\">\n        <div class=\"xmind-branch\"><div class=\"xmind-node\"><strong>آب</strong>مقدار مناسب، آب شیرین</div></div>\n        <div class=\"xmind-branch\"><div class=\"xmind-node\"><strong>خاک</strong>مواد غذایی (خاک باغچه)</div></div>\n        <div class=\"xmind-branch\"><div class=\"xmind-node\"><strong>هوا</strong>اکسیژن برای ریشه</div></div>\n        <div class=\"xmind-branch\"><div class=\"xmind-node\"><strong>نور</strong>برای فتوسنتز</div></div>\n    </div>\n</div>\n\n<!-- TAB: فلش کارت -->\n<h2 style=\"color:#34d399; margin-bottom:15px;\">🃏 فلش کارت‌های آموزشی</h2>\n<p style=\"color:#cbd5e1; margin-bottom:20px;\">برای دیدن پاسخ، روی هر کارت کلیک کنید.</p>\n\n<style>\n    .flashcard-container { display: flex; flex-wrap: wrap; gap: 20px; justify-content: center; }\n    .flashcard { width: 280px; height: 200px; perspective: 1000px; cursor: pointer; }\n    .flashcard-inner { position: relative; width: 100%; height: 100%; text-align: center; transition: transform 0.6s; transform-style: preserve-3d; }\n    .flashcard.flipped .flashcard-inner { transform: rotateY(180deg); }\n    .flashcard-front, .flashcard-back { \n        position: absolute; width: 100%; height: 100%; backface-visibility: hidden; \n        border-radius: 15px; padding: 20px; display: flex; align-items: center; justify-content: center; \n        flex-direction: column; box-shadow: 0 4px 15px rgba(0,0,0,0.3);\n    }\n    .flashcard-front { background: linear-gradient(135deg, #059669, #0d9488); color: white; font-weight: bold; font-size: 1.1rem; border: 2px solid #34d399; }\n    .flashcard-back { background: #0f172a; border: 2px solid #3b82f6; transform: rotateY(180deg); color: #cbd5e1; font-size: 0.95rem; text-align: center; line-height: 1.8; }\n</style>\n\n<div class=\"flashcard-container\">\n    <!-- کارت ۱ -->\n    <div class=\"flashcard\" onclick=\"this.classList.toggle('flipped')\">\n        <div class=\"flashcard-inner\">\n            <div class=\"flashcard-front\">نیازهای اصلی گیاهان چیست؟</div>\n            <div class=\"flashcard-back\">آب، خاک مناسب، هوا و نور خورشید</div>\n        </div>\n    </div>\n\n    <!-- کارت ۲ -->\n    <div class=\"flashcard\" onclick=\"this.classList.toggle('flipped')\">\n        <div class=\"flashcard-inner\">\n            <div class=\"flashcard-front\">آب شور چه تأثیری بر گیاه دارد؟</div>\n            <div class=\"flashcard-back\">برای بیشتر گیاهان مضر است و مانع جذب آب توسط ریشه می‌شود.</div>\n        </div>\n    </div>\n\n    <!-- کارت ۳ -->\n    <div class=\"flashcard\" onclick=\"this.classList.toggle('flipped')\">\n        <div class=\"flashcard-inner\">\n            <div class=\"flashcard-front\">علت خفگی و پژمردگی ریشه چیست؟</div>\n            <div class=\"flashcard-back\">آبیاری بیش از حد و فشرده بودن خاک (نرسیدن اکسیژن به ریشه)</div>\n        </div>\n    </div>\n\n    <!-- کارت ۴ -->\n    <div class=\"flashcard\" onclick=\"this.classList.toggle('flipped')\">\n        <div class=\"flashcard-inner\">\n            <div class=\"flashcard-front\">نقش نور در رشد گیاه چیست؟</div>\n            <div class=\"flashcard-back\">گیاهان با کمک نور خورشید غذای خود را می‌سازند (فتوسنتز).</div>\n        </div>\n    </div>\n</div>\n\n\n<!-- TAB: نکات امتحانی -->\n<h2 style=\"color:#34d399; margin-bottom:15px;\">📝 نکات امتحانی درس یازدهم</h2>\n<div style=\"background:rgba(255,255,255,0.04); border:1px solid rgba(255,255,255,0.08); border-radius:14px; padding:16px 20px; margin-bottom:14px;\">\n    <h4 style=\"color:#fbbf24; margin-bottom:8px; font-size:1rem;\">⚠️ نکته ۱: آبیاری</h4>\n    <p style=\"font-size:0.9rem; color:#cbd5e1; line-height:1.8; margin:0;\">آبیاری زیاد یا کم، هر دو به گیاه آسیب می‌زند. آبیاری باید منظم و به اندازه باشد.</p>\n</div>\n<div style=\"background:rgba(255,255,255,0.04); border:1px solid rgba(255,255,255,0.08); border-radius:14px; padding:16px 20px; margin-bottom:14px;\">\n    <h4 style=\"color:#fbbf24; margin-bottom:8px; font-size:1rem;\">⚠️ نکته ۲: آب شور</h4>\n    <p style=\"font-size:0.9rem; color:#cbd5e1; line-height:1.8; margin:0;\">آب شور به دلیل داشتن نمک زیاد، برای بیشتر گیاهان مضر است و مانع جذب آب توسط ریشه می‌شود.</p>\n</div>\n\n<!-- TAB: آزمون -->\n<h2 style=\"color:#34d399; margin-bottom:15px;\">🧪 آزمون تعاملی درس یازدهم</h2>\n<p style=\"color:#cbd5e1; margin-bottom:20px;\">به سوالات زیر پاسخ دهید و روی دکمه «تصحیح آزمون» کلیک کنید.</p>\n\n<style>\n    .quiz11-option { display: block; padding: 10px; margin: 8px 0; background: rgba(255,255,255,0.05); border: 1px solid rgba(255,255,255,0.1); border-radius: 8px; cursor: pointer; transition: 0.2s; color: #cbd5e1; }\n    .quiz11-option:hover { background: rgba(16,185,129,0.1); border-color: #10b981; }\n    .quiz11-option.correct { background: rgba(34,197,94,0.2) !important; border-color: #22c55e !important; color: #bbf7d0 !important; font-weight: bold; }\n    .quiz11-option.wrong { background: rgba(239,68,68,0.2) !important; border-color: #ef4444 !important; color: #fecaca !important; }\n</style>\n\n<div id=\"quiz11-container\" style=\"background:rgba(255,255,255,0.03); border:1px solid rgba(255,255,255,0.1); padding:20px; border-radius:16px; margin-bottom:20px;\">\n    \n    <!-- سوال ۱ -->\n    <div style=\"margin-bottom:20px; padding-bottom:15px; border-bottom:1px dashed rgba(255,255,255,0.1);\">\n        <p style=\"color:#e2e8f0; font-weight:bold; margin-bottom:10px;\">۱. کدام نوع آب برای رشد بیشتر گیاهان مناسب‌تر است؟</p>\n        <label class=\"quiz11-option\"><input type=\"radio\" name=\"q11_1\" value=\"a\" style=\"margin-left:8px;\"> الف) آب شور</label>\n        <label class=\"quiz11-option q11-correct\"><input type=\"radio\" name=\"q11_1\" value=\"correct\" style=\"margin-left:8px;\"> ب) آب شیرین و معمولی</label>\n        <label class=\"quiz11-option\"><input type=\"radio\" name=\"q11_1\" value=\"c\" style=\"margin-left:8px;\"> ج) آب مقطر</label>\n    </div>\n\n    <!-- سوال ۲ -->\n    <div style=\"margin-bottom:20px; padding-bottom:15px; border-bottom:1px dashed rgba(255,255,255,0.1);\">\n        <p style=\"color:#e2e8f0; font-weight:bold; margin-bottom:10px;\">۲. اگر به گیاهی بیش از حد آب بدهیم، چه اتفاقی می‌افتد؟</p>\n        <label class=\"quiz11-option\"><input type=\"radio\" name=\"q11_2\" value=\"a\" style=\"margin-left:8px;\"> الف) سریع‌تر رشد می‌کند</label>\n        <label class=\"quiz11-option\"><input type=\"radio\" name=\"q11_2\" value=\"b\" style=\"margin-left:8px;\"> ب) برگ‌هایش سبزتر می‌شوند</label>\n        <label class=\"quiz11-option q11-correct\"><input type=\"radio\" name=\"q11_2\" value=\"correct\" style=\"margin-left:8px;\"> ج) ریشه‌ها خفه شده و گیاه پژمرده می‌شود</label>\n    </div>\n\n    <!-- سوال ۳ -->\n    <div style=\"margin-bottom:10px;\">\n        <p style=\"color:#e2e8f0; font-weight:bold; margin-bottom:10px;\">۳. کدام نوع خاک برای کشاورزی و رشد گیاهان بهترین است؟</p>\n        <label class=\"quiz11-option\"><input type=\"radio\" name=\"q11_3\" value=\"a\" style=\"margin-left:8px;\"> الف) خاک شنی</label>\n        <label class=\"quiz11-option q11-correct\"><input type=\"radio\" name=\"q11_3\" value=\"correct\" style=\"margin-left:8px;\"> ب) خاک باغچه (هوموسی)</label>\n        <label class=\"quiz11-option\"><input type=\"radio\" name=\"q11_3\" value=\"c\" style=\"margin-left:8px;\"> ج) خاک رسی</label>\n    </div>\n</div>\n\n<!-- این دکمه با کدهای جاوااسکریپت درون‌خطی کار می‌کند -->\n<button onclick=\"\n    let score = 0;\n    const q1 = document.querySelector('input[name=\\'q11_1\\']:checked');\n    if (q1 && q1.value === 'correct') score++;\n    const q2 = document.querySelector('input[name=\\'q11_2\\']:checked');\n    if (q2 && q2.value === 'correct') score++;\n    const q3 = document.querySelector('input[name=\\'q11_3\\']:checked');\n    if (q3 && q3.value === 'correct') score++;\n    \n    document.querySelectorAll('#quiz11-container .quiz11-option').forEach(el => el.classList.remove('correct', 'wrong'));\n    document.querySelectorAll('#quiz11-container .q11-correct').forEach(el => el.classList.add('correct'));\n    \n    document.querySelectorAll('#quiz11-container input[type=\\'radio\\']:checked').forEach(el => {\n        if (!el.parentElement.classList.contains('q11-correct')) el.parentElement.classList.add('wrong');\n    });\n    \n    const resultBox = document.getElementById('quiz11-result');\n    const scoreEl = document.getElementById('quiz11-score');\n    const feedbackEl = document.getElementById('quiz11-feedback');\n    \n    scoreEl.innerText = score + ' / 3';\n    \n    if (score === 3) { \n        feedbackEl.innerHTML = '🌟 عالی! شما به تمام سوالات پاسخ صحیح دادید.'; \n        feedbackEl.style.color = '#bbf7d0'; \n    } else if (score === 2) { \n        feedbackEl.innerHTML = '👏 خوب! تسلط خوبی دارید، با مرور بیشتر به تسلط کامل می‌رسید.'; \n        feedbackEl.style.color = '#fde68a'; \n    } else { \n        feedbackEl.innerHTML = '📚 نیاز به مطالعه بیشتر دارید. توصیه می‌شود مطالب درس را دوباره مرور کنید.'; \n        feedbackEl.style.color = '#fecaca'; \n    }\n    \n    resultBox.style.display = 'block';\n    resultBox.scrollIntoView({ behavior: 'smooth', block: 'center' });\n\" style=\"width:100%; padding:15px; background:linear-gradient(135deg,#059669,#0d9488); color:#fff; border:none; border-radius:12px; font-size:1.1rem; font-weight:bold; cursor:pointer; transition:0.3s;\">📊 تصحیح آزمون</button>\n\n<div id=\"quiz11-result\" style=\"display:none; margin-top:20px; padding:25px; background:rgba(16,185,129,0.1); border:2px solid #10b981; border-radius:16px; text-align:center;\">\n    <h3 style=\"color:#34d399; margin-bottom:15px;\">🎉 نتیجه آزمون شما</h3>\n    <div id=\"quiz11-score\" style=\"font-size:2.5rem; font-weight:900; color:#fff; margin-bottom:10px;\">۰ / ۳</div>\n    <div id=\"quiz11-feedback\" style=\"font-size:1rem; color:#cbd5e1; line-height:1.8;\"></div>\n</div>\n\n<!-- TAB: گام به گام -->\n<h2 style=\"color:#34d399; margin-bottom:15px;\">✍️ گام به گام درس یازدهم</h2>\n<p style=\"color:#cbd5e1; line-height:1.9;\"><strong>نتیجه آزمایش صفحه ۱۰۰ (آب و رشد گیاه):</strong> گیاهانی که به آن‌ها آب داده نشده بود، پژمرده شدند. گیاهانی که با آب شور آبیاری شدند نیز رشد نکردند. گیاهانی که با آب معمولی آبیاری شدند، بهترین رشد را داشتند. نتیجه می‌گیریم که گیاهان به آب شیرین و کافی نیاز دارند.</p>","r":"rsu2qf"},{"id":"l_1792499839559","title":"12","fullHtml":"<!-- TAB: محتوا -->\n<h2 style=\"color:#34d399; margin-bottom:15px;\">🌳 درس دوازدهم: از ریشه تا برگ</h2>\n<p style=\"color:#cbd5e1; line-height:1.9;\">گیاهان برای زنده ماندن باید آب و مواد غذایی را از خاک جذب کنند و به همه قسمت‌های خود برسانند. همچنین باید با محیط اطراف خود تبادل گاز داشته باشند.</p>\n\n<h3 style=\"color:#6ee7b7; margin-top:20px;\">جذب آب در ریشه</h3>\n<p style=\"color:#cbd5e1; line-height:1.9;\">روی ریشه‌ی گیاهان، تارهای بسیار نازکی به نام <strong>تار کشنده</strong> وجود دارد. این تارها سطح جذب ریشه را افزایش می‌دهند و آب و مواد محلول در خاک را جذب می‌کنند.</p>\n\n<h3 style=\"color:#6ee7b7; margin-top:20px;\">انتقال مواد در ساقه (آوندها)</h3>\n<p style=\"color:#cbd5e1; line-height:1.9;\">آب و مواد جذب شده توسط ریشه، از طریق لوله‌های باریکی به نام <strong>آوند</strong> در ساقه بالا می‌روند و به برگ‌ها می‌رسند. آوندها در برگ‌ها به شکل رگ‌برگ دیده می‌شوند.</p>\n\n<h3 style=\"color:#6ee7b7; margin-top:20px;\">تنفس و تعرق در برگ (روزنه‌ها)</h3>\n<p style=\"color:#cbd5e1; line-height:1.9;\">روی سطح برگ‌ها سوراخ‌های بسیار ریزی به نام <strong>روزنه</strong> وجود دارد. گیاهان از طریق روزنه‌ها با محیط خود تبادل گاز انجام می‌دهند (اکسیژن می‌گیرند و دی‌اکسید کربن دفع می‌کنند) و همچنین بخار آب اضافی خود را از این طریق خارج می‌کنند.</p>\n\n\n<!-- TAB: نمودار درختی -->\n<h2 style=\"color:#34d399; margin-bottom:15px;\">🌳 نمودار درختی از ریشه تا برگ</h2>\n<div class=\"xmind-container\">\n    <div class=\"xmind-root\">انتقال در گیاه</div>\n    <div class=\"xmind-branches\">\n        <div class=\"xmind-branch\"><div class=\"xmind-node\"><strong>ریشه</strong>تار کشنده (جذب آب)</div></div>\n        <div class=\"xmind-branch\"><div class=\"xmind-node\"><strong>ساقه</strong>آوندها (لوله‌های انتقال آب)</div></div>\n        <div class=\"xmind-branch\"><div class=\"xmind-node\"><strong>برگ</strong>رگ‌برگ‌ها (مسیر آوندها)</div></div>\n        <div class=\"xmind-branch\"><div class=\"xmind-node\"><strong>روزنه</strong>تبادل گاز و تعرق</div></div>\n    </div>\n</div>\n\n\n<!-- TAB: نکات امتحانی -->\n<h2 style=\"color:#34d399; margin-bottom:15px;\">📝 نکات امتحانی درس دوازدهم</h2>\n<div style=\"background:rgba(255,255,255,0.04); border:1px solid rgba(255,255,255,0.08); border-radius:14px; padding:16px 20px; margin-bottom:14px;\">\n    <h4 style=\"color:#fbbf24; margin-bottom:8px; font-size:1rem;\">⚠️ نکته ۱: تار کشنده</h4>\n    <p style=\"font-size:0.9rem; color:#cbd5e1; line-height:1.8; margin:0;\">اگر تارهای کشنده ریشه آسیب ببینند، گیاه نمی‌تواند آب جذب کند و از بین می‌رود. هنگام جابه‌جا کردن گلدان باید مراقب خاک اطراف ریشه باشیم.</p>\n</div>\n<div style=\"background:rgba(255,255,255,0.04); border:1px solid rgba(255,255,255,0.08); border-radius:14px; padding:16px 20px; margin-bottom:14px;\">\n    <h4 style=\"color:#fbbf24; margin-bottom:8px; font-size:1rem;\">⚠️ نکته ۲: مالیدن وازلین</h4>\n    <p style=\"font-size:0.9rem; color:#cbd5e1; line-height:1.8; margin:0;\">اگر روی برگ‌ها وازلین بمالیم، روزنه‌ها بسته می‌شوند و گیاه نمی‌تواند تنفس کند، در نتیجه پژمرده می‌شود.</p>\n</div>\n\n\n<!-- TAB: تصاویر مرتبط -->\n<h2 style=\"color:#34d399; margin-bottom:15px;\">🖼️ تصاویر مرتبط با فصل</h2>\n<p style=\"color:#cbd5e1; margin-bottom:20px;\">در این بخش می‌توانید تصاویر مربوط به اجزای گیاه و انتقال مواد را مشاهده کنید. (جهت بزرگ‌نمایی روی تصاویر کلیک کنید)</p>\n\n<div style=\"display:grid; grid-template-columns:repeat(auto-fit, minmax(250px, 1fr)); gap:20px;\">\n    <div style=\"background:rgba(255,255,255,0.05); border-radius:12px; padding:15px; text-align:center;\">\n        <div style=\"font-size:4rem; margin-bottom:10px;\">🌱</div>\n        <h4 style=\"color:#34d399; margin-bottom:10px;\">تارهای کشنده ریشه</h4>\n        <p style=\"color:#94a3b8; font-size:0.85rem;\">تارهای بسیار نازک روی ریشه که وظیفه جذب آب و مواد محلول را بر عهده دارند.</p>\n    </div>\n    \n    <div style=\"background:rgba(255,255,255,0.05); border-radius:12px; padding:15px; text-align:center;\">\n        <div style=\"font-size:4rem; margin-bottom:10px;\">🪴</div>\n        <h4 style=\"color:#34d399; margin-bottom:10px;\">آوندها در ساقه</h4>\n        <p style=\"color:#94a3b8; font-size:0.85rem;\">لوله‌های باریک درون ساقه که آب را از ریشه به برگ‌ها منتقل می‌کنند.</p>\n    </div>\n\n    <div style=\"background:rgba(255,255,255,0.05); border-radius:12px; padding:15px; text-align:center;\">\n        <div style=\"font-size:4rem; margin-bottom:10px;\">🍃</div>\n        <h4 style=\"color:#34d399; margin-bottom:10px;\">روزنه‌های برگ</h4>\n        <p style=\"color:#94a3b8; font-size:0.85rem;\">سوراخ‌های ریز روی برگ که محل تبادل گاز (تنفس) و تعرق گیاه هستند.</p>\n    </div>\n</div>\n\n<div style=\"margin-top:20px; background:rgba(59,130,246,0.1); border:1px dashed #3b82f6; border-radius:12px; padding:15px; color:#93c5fd; font-size:0.9rem; text-align:center;\">\n    📌 <strong>راهنما برای ادمین:</strong> شما می‌توانید با جایگزین کردن تگ‌های <code>&lt;div&gt;</code> بالا با تگ <code>&lt;img src=\"آدرس عکس\"&gt;</code>، عکس‌های واقعی کتاب را در این بخش قرار دهید.\n</div>\n\n\n<!-- TAB: آزمون -->\n<h2 style=\"color:#34d399; margin-bottom:15px;\">🧪 آزمون تستی درس دوازدهم</h2>\n<p style=\"color:#cbd5e1; margin-bottom:20px;\">به سوالات زیر پاسخ دهید و در انتها روی دکمه «مشاهده نتیجه» کلیک کنید.</p>\n\n<div id=\"quiz12-container\" style=\"background:rgba(255,255,255,0.03); border:1px solid rgba(255,255,255,0.1); padding:20px; border-radius:16px; margin-bottom:20px;\">\n    \n    <!-- سوال ۱ -->\n    <div style=\"margin-bottom:20px; padding-bottom:15px; border-bottom:1px dashed rgba(255,255,255,0.1);\">\n        <p style=\"color:#e2e8f0; font-weight:bold; margin-bottom:10px;\">۱. کدام بخش گیاه وظیفه جذب آب و مواد محلول را بر عهده دارد؟</p>\n        <label style=\"display:block; padding:8px; cursor:pointer; color:#cbd5e1;\"><input type=\"radio\" name=\"q12_1\" value=\"a\" style=\"margin-left:8px;\"> الف) برگ</label>\n        <label style=\"display:block; padding:8px; cursor:pointer; color:#cbd5e1;\"><input type=\"radio\" name=\"q12_1\" value=\"b\" style=\"margin-left:8px;\"> ب) تارهای کشنده ریشه</label>\n        <label style=\"display:block; padding:8px; cursor:pointer; color:#cbd5e1;\"><input type=\"radio\" name=\"q12_1\" value=\"c\" style=\"margin-left:8px;\"> ج) گل</label>\n    </div>\n\n    <!-- سوال ۲ -->\n    <div style=\"margin-bottom:20px; padding-bottom:15px; border-bottom:1px dashed rgba(255,255,255,0.1);\">\n        <p style=\"color:#e2e8f0; font-weight:bold; margin-bottom:10px;\">۲. تبادل گاز در برگ گیاهان از طریق چه چیزی انجام می‌شود؟</p>\n        <label style=\"display:block; padding:8px; cursor:pointer; color:#cbd5e1;\"><input type=\"radio\" name=\"q12_2\" value=\"a\" style=\"margin-left:8px;\"> الف) رگ‌برگ</label>\n        <label style=\"display:block; padding:8px; cursor:pointer; color:#cbd5e1;\"><input type=\"radio\" name=\"q12_2\" value=\"b\" style=\"margin-left:8px;\"> ب) آوند</label>\n        <label style=\"display:block; padding:8px; cursor:pointer; color:#cbd5e1;\"><input type=\"radio\" name=\"q12_2\" value=\"c\" style=\"margin-left:8px;\"> ج) روزنه</label>\n    </div>\n\n    <!-- سوال ۳ -->\n    <div style=\"margin-bottom:10px;\">\n        <p style=\"color:#e2e8f0; font-weight:bold; margin-bottom:10px;\">۳. آب و مواد غذایی پس از جذب توسط ریشه، از طریق کدام قسمت به برگ می‌رسند؟</p>\n        <label style=\"display:block; padding:8px; cursor:pointer; color:#cbd5e1;\"><input type=\"radio\" name=\"q12_3\" value=\"a\" style=\"margin-left:8px;\"> الف) آوندها در ساقه</label>\n        <label style=\"display:block; padding:8px; cursor:pointer; color:#cbd5e1;\"><input type=\"radio\" name=\"q12_3\" value=\"b\" style=\"margin-left:8px;\"> ب) روزنه‌ها</label>\n        <label style=\"display:block; padding:8px; cursor:pointer; color:#cbd5e1;\"><input type=\"radio\" name=\"q12_3\" value=\"c\" style=\"margin-left:8px;\"> ج) تارهای کشنده</label>\n    </div>\n\n</div>\n\n<button onclick=\"evalLesson12Quiz()\" style=\"width:100%; padding:15px; background:linear-gradient(135deg,#059669,#0d9488); color:#fff; border:none; border-radius:12px; font-size:1.1rem; font-weight:bold; cursor:pointer; transition:0.3s;\">📊 مشاهده نتیجه آزمون</button>\n\n<div id=\"quiz12-result-box\" style=\"display:none; margin-top:20px; padding:25px; background:rgba(16,185,129,0.1); border:2px solid #10b981; border-radius:16px; text-align:center;\">\n    <h3 style=\"color:#34d399; margin-bottom:15px;\">🎉 نتیجه آزمون شما</h3>\n    <div id=\"quiz12-score\" style=\"font-size:2.5rem; font-weight:900; color:#fff; margin-bottom:10px;\">۰ / ۳</div>\n    <div id=\"quiz12-feedback\" style=\"font-size:1rem; color:#cbd5e1; line-height:1.8;\"></div>\n</div>\n\n\n<!-- TAB: سوالات نیمه اول -->\n<h2 style=\"color:#34d399; margin-bottom:15px;\">📝 سوالات نیمه اول علوم (دروس ۱ تا ۶)</h2>\n<p style=\"color:#cbd5e1; margin-bottom:20px;\">این سوالات برای مرور و آمادگی در امتحانات نیمه اول سال تحصیلی طراحی شده‌اند.</p>\n\n<div style=\"background:rgba(255,255,255,0.04); border:1px solid rgba(255,255,255,0.08); border-radius:14px; padding:20px; margin-bottom:15px;\">\n    <h4 style=\"color:#fbbf24; margin-bottom:10px;\">۱. مراحل روش علمی را به ترتیب بنویسید.</h4>\n    <p style=\"color:#94a3b8; font-size:0.9rem; margin-top:10px; border-top:1px dashed rgba(255,255,255,0.1); padding-top:10px;\">پاسخ: مشاهده ← پرسش ← فرضیه‌سازی ← آزمایش ← نتیجه‌گیری</p>\n</div>\n\n<div style=\"background:rgba(255,255,255,0.04); border:1px solid rgba(255,255,255,0.08); border-radius:14px; padding:20px; margin-bottom:15px;\">\n    <h4 style=\"color:#fbbf24; margin-bottom:10px;\">۲. تفاوت تغییر فیزیکی و شیمیایی را با ذکر مثال بنویسید.</h4>\n    <p style=\"color:#94a3b8; font-size:0.9rem; margin-top:10px; border-top:1px dashed rgba(255,255,255,0.1); padding-top:10px;\">پاسخ: در تغییر فیزیکی، شکل و ظاهر ماده عوض می‌شود اما جنس ماده تغییر نمی‌کند (مثل خرد کردن چوب). در تغییر شیمیایی، ماده جدیدی تولید می‌شود (مثل سوختن کاغذ).</p>\n</div>\n\n<div style=\"background:rgba(255,255,255,0.04); border:1px solid rgba(255,255,255,0.08); border-radius:14px; padding:20px; margin-bottom:15px;\">\n    <h4 style=\"color:#fbbf24; margin-bottom:10px;\">۳. رنگین کمان چگونه تشکیل می‌شود؟</h4>\n    <p style=\"color:#94a3b8; font-size:0.9rem; margin-top:10px; border-top:1px dashed rgba(255,255,255,0.1); padding-top:10px;\">پاسخ: وقتی نور خورشید (نور سفید) از میان قطرات آب باران عبور می‌کند، قطرات آب مانند منشور عمل کرده و نور را به رنگ‌های مختلف تجزیه می‌کنند.</p>\n</div>\n\n<div style=\"background:rgba(255,255,255,0.04); border:1px solid rgba(255,255,255,0.08); border-radius:14px; padding:20px; margin-bottom:15px;\">\n    <h4 style=\"color:#fbbf24; margin-bottom:10px;\">۴. فسیل چیست و در کدام لایه‌های زمین قدیمی‌تر است؟</h4>\n    <p style=\"color:#94a3b8; font-size:0.9rem; margin-top:10px; border-top:1px dashed rgba(255,255,255,0.1); padding-top:10px;\">پاسخ: فسیل به آثار و بقایای جانداران گذشته گفته می‌شود که در لایه‌های رسوبی باقی مانده‌اند. فسیل‌های موجود در لایه‌های پایین‌تر، قدیمی‌تر هستند.</p>\n</div>\n\n<div style=\"background:rgba(255,255,255,0.04); border:1px solid rgba(255,255,255,0.08); border-radius:14px; padding:20px; margin-bottom:15px;\">\n    <h4 style=\"color:#fbbf24; margin-bottom:10px;\">۵. سه بخش اصلی یک اهرم را نام ببرید.</h4>\n    <p style=\"color:#94a3b8; font-size:0.9rem; margin-top:10px; border-top:1px dashed rgba(255,255,255,0.1); padding-top:10px;\">پاسخ: ۱- تکیه‌گاه ۲- محل وارد شدن نیرو ۳- محل قرار گرفتن جسم (بار)</p>\n</div>\n\n<div style=\"background:rgba(255,255,255,0.04); border:1px solid rgba(255,255,255,0.08); border-radius:14px; padding:20px; margin-bottom:15px;\">\n    <h4 style=\"color:#fbbf24; margin-bottom:10px;\">۶. مسیر دیدن اجسام در چشم را به ترتیب بنویسید.</h4>\n    <p style=\"color:#94a3b8; font-size:0.9rem; margin-top:10px; border-top:1px dashed rgba(255,255,255,0.1); padding-top:10px;\">پاسخ: نور از قرنیه و مردمک عبور کرده، توسط عدسی روی شبکیه متمرکز می‌شود. سلول‌های شبکیه پیام را از طریق عصب بینایی به مغز می‌فرستند.</p>\n</div>\n\n\n<!-- اسکریپت تعاملی آزمون -->\n<script>\nfunction evalLesson12Quiz() {\n    // پاسخ‌های صحیح\n    const answers = { q12_1: 'b', q12_2: 'c', q12_3: 'a' };\n    let score = 0;\n    \n    // بررسی سوال ۱\n    if(document.querySelector('input[name=\"q12_1\"]:checked')?.value === answers.q12_1) score++;\n    \n    // بررسی سوال ۲\n    if(document.querySelector('input[name=\"q12_2\"]:checked')?.value === answers.q12_2) score++;\n    \n    // بررسی سوال ۳\n    if(document.querySelector('input[name=\"q12_3\"]:checked')?.value === answers.q12_3) score++;\n\n    // نمایش نتیجه\n    const resultBox = document.getElementById('quiz12-result-box');\n    const scoreEl = document.getElementById('quiz12-score');\n    const feedbackEl = document.getElementById('quiz12-feedback');\n    \n    scoreEl.innerText = `${score} / 3`;\n    \n    if (score === 3) {\n        feedbackEl.innerHTML = '🌟 عالی! شما به تمام سوالات پاسخ صحیح دادید.';\n        feedbackEl.style.color = '#bbf7d0';\n    } else if (score === 2) {\n        feedbackEl.innerHTML = '👏 خوب! تسلط خوبی دارید، با مرور بیشتر به تسلط کامل می‌رسید.';\n        feedbackEl.style.color = '#fde68a';\n    } else {\n        feedbackEl.innerHTML = '📚 نیاز به مطالعه بیشتر دارید. توصیه می‌شود مطالب درس را دوباره مرور کنید.';\n        feedbackEl.style.color = '#fecaca';\n    }\n    \n    resultBox.style.display = 'block';\n    resultBox.scrollIntoView({ behavior: 'smooth', block: 'center' });\n}\n</script>","r":"hpfsh6"}]};